import secrets
def new_api_token(prefix="cz_", nbytes=24):

# 24 random bytes, URL-safe, e.g. cz_<32 chars>
return prefix + secrets.token_urlsafe(nbytes)

def is _valid(token):
return token.startswith("cz_") and len(token) == 35
